#!/usr/bin/env python3
"""Independent reimplementation of the S57 seat-artifact aggregation (S58).
Reads tests/results/*.json (runner-*/adv-*/compliance-*), extracts per-tool
metrics with per-file honesty (null where a file does not expose the data),
and prints an aggregation JSON on stdout. Read-only."""
import json,os,sys,hashlib,glob

REPO=sys.argv[1] if len(sys.argv)>1 else "/home/vgpnk/Projects/shokunin/souji-shokunin"
RES=os.path.join(REPO,"tests/results")
TOOLS=os.path.join(REPO,"tools")

def sha12(p):
    try: return hashlib.sha256(open(p,'rb').read()).hexdigest()[:12]
    except OSError: return None

current={}
for p in sorted(glob.glob(os.path.join(TOOLS,"souji-verify*.sh"))):
    current[os.path.basename(p)]=sha12(p)

def norm_tool_basename(path):
    if not path: return None
    return os.path.basename(path)

def runner_metrics(d):
    """Return (passed,total,basis) or None."""
    t=d.get("totals") or {}
    if isinstance(t,dict) and t.get("cases"):
        return (t.get("passed",0), t.get("cases"), "totals.passed/cases")
    s=d.get("summary") or {}
    if isinstance(s,dict):
        total=None; passed=None
        for k in ("cases_total","cases","checks","total"):
            if isinstance(s.get(k),int): total=s[k]; break
        for k in ("passed","pass","ok"):
            if isinstance(s.get(k),int): passed=s[k]; break
        if total and passed is not None and total>0:
            return (passed,total,"summary.passed/total")
    cases=d.get("cases")
    if isinstance(cases,list) and cases and all(isinstance(c,dict) for c in cases):
        if all("pass" in c for c in cases):
            return (sum(1 for c in cases if c["pass"] in (True,"True","true")),len(cases),"cases[].pass")
        for key in ("result","status","outcome","verdict"):
            if all(key in c for c in cases):
                passed=sum(1 for c in cases
                           if str(c[key]).strip().lower() in ("pass","passed","ok","true","yes"))
                return (passed,len(cases),"cases[].%s"%key)
    r=d.get("results")
    if isinstance(r,list) and r and all(isinstance(c,dict) for c in r):
        if "passed" in r[0] and "total" in r[0]:
            return (sum(x.get("passed",0) for x in r), sum(x.get("total",0) for x in r),"results[].passed/total")
    return None

def adv_metrics(d):
    s=d.get("summary") or {}
    if isinstance(s,dict):
        bp,bf=s.get("binding_pass"),s.get("binding_fail")
        if isinstance(bp,int) and isinstance(bf,int) and bp+bf>0:
            return (bp,bp+bf,"summary.binding_pass/(pass+fail)")
        for pk,tk,label in (("survived","total","survived/total"),
                            ("cases_pass","cases_total","cases_pass/cases_total"),
                            ("pass","total","pass/total"),
                            ("pass","cases_run","pass/cases_run"),
                            ("scored_pass","scored","scored_pass/scored"),
                            ("passed","cases_total","passed/cases_total")):
            pv,tv=s.get(pk),s.get(tk)
            if isinstance(pv,int) and isinstance(tv,int) and tv>0:
                return (pv,tv,"summary."+label)
    cases=d.get("cases")
    if isinstance(cases,list) and cases and all(isinstance(c,dict) for c in cases):
        bind=[c for c in cases if c.get("binding")]
        if bind and all("result" in c for c in bind):
            ok=sum(1 for c in bind if str(c["result"]).strip().lower() in ("pass","passed","ok","true"))
            return (ok,len(bind),"cases[].result (binding)")
    return None

def compliance_all_pass(d, impl):
    if impl in d and isinstance(d[impl],dict) and "all_pass" in d[impl]:
        return bool(d[impl]["all_pass"])
    v=d.get("verdict")
    if isinstance(v,str):
        return v.strip().upper() in ("COMPLIANT","PASS","ALL-PASS")
    return None

impls=set(current)
files=sorted(glob.glob(os.path.join(RES,"*.json")))
files=[f for f in files if os.path.basename(f) not in ("final-57.json","final-58.json")]
inv=[]; runners=[]; advs=[]; comps=[]
for f in files:
    base=os.path.basename(f)
    kind=base.split("-")[0]
    size=os.path.getsize(f)
    entry={"file":"tests/results/"+base,"kind":kind,"bytes":size,"sha256_12":sha12(f)}
    if size==0:
        entry["note"]="empty"; inv.append(entry); continue
    try:
        d=json.load(open(f))
    except Exception as e:
        entry["note"]="parse-error: %s"%e; inv.append(entry); continue
    if not isinstance(d,dict):
        entry["note"]="non-object JSON"; inv.append(entry); continue
    tool=d.get("tool") if isinstance(d.get("tool"),dict) else {}
    tpath=tool.get("path") or d.get("tool_path")
    tsha=tool.get("sha256") or d.get("tool_sha256")
    name=norm_tool_basename(tpath)
    entry.update({"tool_path":tpath,"tool_sha256":tsha,"impl":name})
    if kind=="runner":
        m=runner_metrics(d)
        entry["verdict"]=d.get("verdict")
        entry["metrics"]=m[:2] if m else None
        entry["metric_basis"]=m[2] if m else None
        runners.append(entry); impls.add(name) if name else None
    elif kind=="adv":
        m=adv_metrics(d)
        entry["verdict"]=d.get("verdict")
        entry["metrics"]=m[:2] if m else None
        entry["metric_basis"]=m[2] if m else None
        advs.append(entry); impls.add(name) if name else None
    elif kind=="compliance":
        per={}
        for k in impls|set(current):
            ap=compliance_all_pass(d,k)
            if ap is not None: per[k]=ap
        entry["per_impl_all_pass"]=per
        entry["impl"]=name
        comps.append(entry)
    else:
        entry["note"]="unrecognized kind"
    inv.append(entry)

impls.discard(None)
per_impl={}
for impl in sorted(impls):
    cur_sha=current.get(impl)
    def basis_match(e):
        tsha=e.get("tool_sha256")
        if tsha and cur_sha:
            return tsha[:12]==cur_sha[:12]
        return e.get("impl")==impl and not tsha
    r_cur=[e for e in runners if e.get("impl")==impl and basis_match(e) and e.get("metrics")]
    r_all=[e for e in runners if e.get("impl")==impl and e.get("metrics")]
    a_cur=[e for e in advs if e.get("impl")==impl and basis_match(e) and e.get("metrics")]
    a_all=[e for e in advs if e.get("impl")==impl and e.get("metrics")]
    def rate_macro(lst):
        if not lst: return None
        return sum(p/t for p,t in (e["metrics"] for e in lst))/(len(lst))
    def rate_micro(lst):
        if not lst: return None
        P=sum(e["metrics"][0] for e in lst); T=sum(e["metrics"][1] for e in lst)
        return P/T if T else None
    comp_cur=[]; comp_all=[]
    for e in comps:
        ap=e["per_impl_all_pass"].get(impl)
        if ap is None: continue
        comp_all.append(ap)
        if e.get("impl") is None or basis_match(e): comp_cur.append(ap)
    per_impl[impl]={
        "on_disk":impl in current,
        "current_sha12":cur_sha,
        "runner_pass_rate":rate_macro(r_cur),"runner_pass_rate_micro":rate_micro(r_cur),
        "runner_passed":sum(e["metrics"][0] for e in r_cur) if r_cur else None,
        "runner_total":sum(e["metrics"][1] for e in r_cur) if r_cur else None,
        "runner_current_files":len(r_cur),"runner_macro_files":len(r_all),
        "runner_pass_rate_stale_mix":rate_macro(r_all),
        "adv_survival":rate_macro(a_cur),"adv_survival_micro":rate_micro(a_cur),
        "adv_survival_all_versions":rate_macro(a_all),"adv_survival_micro_all_versions":rate_micro(a_all),
        "adv_survived":sum(e["metrics"][0] for e in a_cur) if a_cur else None,
        "adv_total":sum(e["metrics"][1] for e in a_cur) if a_cur else None,
        "adv_macro_files":len(a_all),
        "compliance_all_pass":(all(comp_cur) if comp_cur else None),
        "compliance_all_pass_all_versions":(all(comp_all) if comp_all else None),
    }
def key(impl):
    m=per_impl[impl]
    return (
        1 if m["on_disk"] else 0,
        m["runner_pass_rate"] if m["runner_pass_rate"] is not None else -1,
        m["runner_pass_rate_micro"] if m["runner_pass_rate_micro"] is not None else -1,
        m["adv_survival"] if m["adv_survival"] is not None else -1,
        1 if m["compliance_all_pass"] else 0,
        impl,
    )
ranking=sorted(per_impl,key=key,reverse=True)
winner=ranking[0] if ranking and per_impl[ranking[0]]["on_disk"] else (ranking[0] if ranking else None)
out={
 "seat":"S58","role":"seat-artifact aggregation (independent reimplementation of S57 rule)",
 "source":"tests/results/*.json excluding final-57/final-58",
 "selection_order":["on_disk","runner_pass_rate","runner_pass_rate_micro","adv_survival","compliance_all_pass","name"],
 "winner":winner,
 "ranking":ranking,
 "per_impl":per_impl,
 "artifact_counts":{"runner":len(runners),"adv":len(advs),"compliance":len(comps),
                    "runner_scored":sum(1 for e in runners if e.get("metrics")),
                    "adv_scored":sum(1 for e in advs if e.get("metrics")),
                    "empty_or_unparsed":sum(1 for e in inv if e.get("note"))},
 "input_files":inv,
}
print(json.dumps(out,indent=1))
